'use strict';

/** @param {string} text @param {string} suffix */
function endsWith(text, suffix) {
  return text.length >= suffix.length && text.slice(text.length - suffix.length) === suffix;
}

/** @param {string} path */
function normalize(path) {
  if (path.length === 0) {
    return '/';
  }
  if (path.charAt(0) !== '/') {
    return '/' + path;
  }
  return path;
}

/** @param {string} path */
function isSendable(path) {
  return path.indexOf('..') < 0 && path.indexOf('\0') < 0;
}

/** @param {string} file */
function contentType(file) {
  if (endsWith(file, '.html')) {
    return 'text/html';
  }
  if (endsWith(file, '.json')) {
    return 'application/json';
  }
  if (endsWith(file, '.css')) {
    return 'text/css';
  }
  return 'application/octet-stream';
}

exports.normalize = normalize;
exports.isSendable = isSendable;
exports.contentType = contentType;
